  if (tick !== lastSeenTick) {
    lastSeenTick = tick;
    lastSeenTickTime = Date.now();
  } else if (Date.now() - lastSeenTickTime > 15000) {
    throw new Error('[fish-grind] Game tick frozen for 15 seconds!');
  }
}

